-- +----------------------------------------------------------------------
-- | CRMEB 多言語パッチ: 中国語 / English / 日本語 の3言語対応
-- +----------------------------------------------------------------------
-- | 適用: mysql -u<user> -p <database> < lang_zh_en_ja.sql
-- | 適用後、管理画面のキャッシュクリア（またはキャッシュ削除）を実行してください。
-- | テーブル接頭辞が eb_ 以外の場合は一括置換してください。
-- +----------------------------------------------------------------------

SET NAMES utf8mb4;

-- ============================================================
-- 1. 言語タイプ: 中国語(1) / English(2) / 日本語(6) のみ有効化
--    ※ 他言語は status=0 にするだけでデータは残すため、いつでも再有効化できます。
-- ============================================================
UPDATE `eb_lang_type` SET `status` = 1 WHERE `id` IN (1, 2, 6);
UPDATE `eb_lang_type` SET `status` = 0 WHERE `id` NOT IN (1, 2, 6);

-- ============================================================
-- 2. ブラウザ言語コード → 言語タイプ の対応を補完
--    既存は 'zh-CN' / 'en-US' / 'ja-JP' のみ対応しており、
--    navigator.language が 'ja' や 'en-GB' を返す環境で中国語に
--    フォールバックしてしまうため、変種コードも割り当てます。
-- ============================================================
UPDATE `eb_lang_country` SET `type_id` = 6 WHERE `code` IN ('ja', 'ja-JP');
UPDATE `eb_lang_country` SET `type_id` = 2 WHERE `code` = 'en' OR `code` LIKE 'en-%';
UPDATE `eb_lang_country` SET `type_id` = 1 WHERE `code` IN ('zh', 'zh-CN', 'zh-Hans', 'zh-SG');

-- 'zh-Hans' は初期データに存在しないため、無ければ追加
INSERT INTO `eb_lang_country` (`type_id`, `code`, `name`)
SELECT 1, 'zh-Hans', '中文(简体)' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `eb_lang_country` WHERE `code` = 'zh-Hans');

