UPDATE `eb_lang_code` SET `lang_explain` = 'サービス契約とプライバシーポリシーの条項を注意深く読み、完全に理解してください。これには、インスタントメッセージング、コンテンツ共有、およびその他のサービスを提供するために、デバイスを収集する必要があります。情報、操作ログ、その他の個人情報。個人情報を表示、変更、削除し、[設定]で承認を管理できます。' WHERE `type_id` = 6 AND `code` = '请务必审慎阅读、充分理解“服务协议与 隐私政策”各条款，包括但不限于：为了 向你提供即时通讯、内容分享等服务，我 们需要收集你的设备信息、操作日志等个 人信息。你可以在“设置”中查看、变更、删除个人信息并管理你的授权。';
